const A:PlayerId=PlayerId::from_index(0);const B:PlayerId=PlayerId::from_index(1);
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/revolution-reprieve-pursuit-complete.json")).unwrap()}
fn actual(name:&str)->[CardDefinition;2]{let fixture=fixture();let source=fixture["mechanics"].as_array().unwrap().iter().flat_map(|row|row["representative_cards"].as_array().unwrap()).find(|card|card["name"]==name).unwrap();support::definitions(source).unwrap_or_else(|error|panic!("{name}: {error}"))}
#[test]fn all_twenty_four_physical_sources_compile_direct_and_serialized_without_loss(){let fixture=fixture();let mut names=std::collections::BTreeSet::new();for row in fixture["mechanics"].as_array().unwrap(){for source in row["representative_cards"].as_array().unwrap(){assert!(source["executable_text"].as_str().is_some(),"parent must materialize {}",source["name"]);support::definitions(source).unwrap_or_else(|error|panic!("{}: {error}",source["name"]));names.insert(source["source_card_key"].as_str().unwrap());}}assert_eq!(names, ["Architect of Resolve_TWI","Become the Hunted_VLR","Boundlight Seraph_TWI","Choir Ascendant_TWI","Dawnhymn Herald_TWI","Dawnspark Vanguard_TWI","End the Chase_VLR","Guild Elite_VLR","Gutter Rat_VLR","Hired Hand_VLR","Lunate Prowlwarden_TWI","Lunate Sentinel_TWI","Paragon of Sacred Bellows_TWI","Patient Executioner_VLR","Purifier of Dawnbloom Grove_TWI","Ruthless Stalker_VLR","Sanctum of Repression_TWI","Shaper of Luminous Will_TWI","Slinking Swiftblade_VLR","Softlight Harmonist_TWI","The Founder's Hunt Begins_VLR","Unerring Killer_VLR","Veteran Hunter_VLR","Winding Assailant_VLR"].into_iter().collect(),"exact operative physical-source universe from both-face corpus audit");}
struct EntryChoices(VecDeque<bool>);impl DecisionMaker for EntryChoices{fn decide_boolean(&mut self,_:&GameState,_:&ironsmith::decisions::context::BooleanContext)->bool{self.0.pop_front().expect("one Boolean per independent source entry opportunity")}}
fn enter(game:&mut GameState,old:ObjectId,dm:&mut impl DecisionMaker)->ObjectId{
 let stable=game.object(old).unwrap().stable_id;
 let effect=ironsmith::Effect::put_onto_battlefield(ChooseSpec::SpecificObject(old),false,PlayerFilter::You);
 let outcome=execute_effect(game,&effect,&mut EffectContext::new(old,A,dm)).unwrap();
 for event in outcome.events{game.queue_trigger_event(event.provenance(),event);}
 game.find_object_by_stable_id(stable).unwrap()
}
fn drain(game:&mut GameState,dm:&mut impl DecisionMaker){let mut queue=ironsmith::triggers::TriggerQueue::new();ironsmith::game_loop::drain_pending_trigger_events_with_dm(game,&mut queue,dm).unwrap();ironsmith::game_loop::put_triggers_on_stack_with_dm(game,&mut queue,dm).unwrap();}
#[test]fn all_twelve_entry_sources_have_independent_opportunities_and_exclude_marked_creatures(){
 let fixture=fixture();let mut names=std::collections::BTreeSet::new();
 for row in fixture["mechanics"].as_array().unwrap().iter().filter(|row|row["keyword"]=="Reprieve"){for source in row["representative_cards"].as_array().unwrap(){let name=source["name"].as_str().unwrap();if !names.insert(name){continue;}for definition in support::definitions(source).unwrap(){for accept in [false,true]{let mut game=play::game();let marked=game.create_object_from_definition(&definition,A,Zone::Battlefield);let opportunities=if name=="Choir Ascendant"{3}else{1};let creature=play::vanilla("Returnable independent creature","{1}","Elf",1,1);let victims:Vec<_>=(0..opportunities).map(|_|{let id=game.create_object_from_definition(&creature,A,Zone::Battlefield);game.object(id).unwrap().stable_id}).collect();let old=game.create_object_from_definition(&definition,A,Zone::Hand);let mut choices=EntryChoices(std::iter::repeat_n(accept,opportunities).collect());let arrived=enter(&mut game,old,&mut choices);assert!(choices.0.is_empty(),"{name}");assert_eq!(game.named_action_count(arrived,"reprieve",false),if accept{opportunities as u32}else{0},"{name}");assert_eq!(game.object(marked).unwrap().zone,Zone::Battlefield);assert_eq!(victims.iter().filter(|stable|game.find_object_by_stable_id(**stable).is_some_and(|id|game.object(id).unwrap().zone==Zone::Hand)).count(),if accept{opportunities}else{0},"{name}");}}}}
 assert_eq!(names.len(),12);
}
fn action(game:&GameState,donor:ObjectId)->Option<LegalAction>{compute_legal_actions(game,A).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,from_zone:Zone::Graveyard,..}if *spell_id==donor))}
fn announce(game:&mut GameState,selected:LegalAction)->Result<ObjectId,String>{
 use ironsmith::game_loop::{PriorityLoopState,PriorityResponse,apply_priority_response_with_dm,apply_decision_context_with_dm};
 let mut state=PriorityLoopState::new(3);let mut queue=ironsmith::triggers::TriggerQueue::new();let mut dm=SelectFirstDecisionMaker;
 let mut progress=apply_priority_response_with_dm(game,&mut queue,&mut state,&PriorityResponse::PriorityAction(selected),&mut dm).map_err(|e|format!("{e:?}"))?;
 for _ in 0..100{if !state.has_pending_action(){let spell=game.stack.iter().find(|entry|!entry.is_ability).ok_or("cast did not produce a spell")?.object_id;ironsmith::game_loop::put_triggers_on_stack_with_dm(game,&mut queue,&mut dm).map_err(|e|format!("{e:?}"))?;return Ok(spell);}let ironsmith::GameProgress::NeedsDecisionCtx(context)=progress else{return Err(format!("{progress:?}"));};progress=apply_decision_context_with_dm(game,&mut queue,&mut state,&context,&mut dm).map_err(|e|format!("{e:?}"))?;}Err("cast did not finish".into())
}
fn mana(game:&mut GameState){for symbol in [ironsmith::mana::ManaSymbol::Black,ironsmith::mana::ManaSymbol::Green]{game.player_mut(A).unwrap().mana_pool.add(symbol,20);}}
#[test]fn actual_guild_elite_requires_sacrifice_and_pays_a_separate_donor_before_copy_becomes_token(){for definition in actual("Guild Elite"){for supply in [false,true]{let mut game=play::game();mana(&mut game);let donor=game.create_object_from_definition(&definition,A,Zone::Graveyard);let stable=game.object(donor).unwrap().stable_id;let fodder=ironsmith_compiler_runtime::compile_to_runtime_definition("Sacrifice artifact","Type: Artifact",false).unwrap();let fodder=supply.then(||game.create_object_from_definition(&fodder,A,Zone::Battlefield));let selected=action(&game,donor);if !supply{assert!(selected.is_none());continue;}let fodder_stable=game.object(fodder.unwrap()).unwrap().stable_id;let copy=announce(&mut game,selected.unwrap()).unwrap();assert_ne!(game.object(copy).unwrap().stable_id,stable);assert_eq!(game.cast_origin_snapshot(copy).unwrap().object_id,donor);assert_eq!(game.cast_origin_snapshot(copy).unwrap().zone,Zone::Graveyard);assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Exile);assert_eq!(game.object(game.find_object_by_stable_id(fodder_stable).unwrap()).unwrap().zone,Zone::Graveyard);ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();assert!(game.battlefield.iter().filter_map(|id|game.object(*id)).any(|object|object.name=="Guild Elite"&&object.kind==ironsmith::object::ObjectKind::Token));}}}
#[test]fn actual_winding_has_one_paid_cast_trigger_and_two_permanent_copies_without_repaying_costs(){for definition in actual("Winding Assailant"){let mut game=play::game();game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Green,6);let donor=game.create_object_from_definition(&definition,A,Zone::Graveyard);let stable=game.object(donor).unwrap().stable_id;let fodder=ironsmith_compiler_runtime::compile_to_runtime_definition("One sacrifice","Type: Artifact",false).unwrap();game.create_object_from_definition(&fodder,A,Zone::Battlefield);let selected=action(&game,donor).unwrap();announce(&mut game,selected).unwrap();assert_eq!(game.stack.len(),2,"actual paid-cast trigger sits above the original copy");ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();assert_eq!(game.stack.len(),2,"trigger copied the spell but did not cast it again");while !game.stack.is_empty(){ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();}assert_eq!(game.battlefield.iter().filter_map(|id|game.object(*id)).filter(|object|object.name=="Winding Assailant"&&object.kind==ironsmith::object::ObjectKind::Token).count(),2);assert_eq!(game.player(A).unwrap().mana_pool.total(),0);assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Exile);}}

#[test]fn actual_architect_preserves_unwindowed_departure_history_and_excludes_deaths_and_opponents(){
 for definition in actual("Architect of Resolve"){for (owner,destination,expected) in [(A,Zone::Hand,2),(A,Zone::Graveyard,0),(B,Zone::Hand,0)]{
  let mut game=play::game();let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);
  let other=game.create_object_from_definition(&play::vanilla("Historical creature","{1}","Elf",1,1),owner,Zone::Battlefield);
  let effect=ironsmith::Effect::move_to_zone(ChooseSpec::SpecificObject(other),destination,false);
  let result=execute_effect(&mut game,&effect,&mut EffectContext::new_default(source,A)).unwrap();
  for event in result.events{game.queue_trigger_event(event.provenance(),event);}
  drain(&mut game,&mut SelectFirstDecisionMaker);
  game.next_turn();game.next_turn();game.next_turn();
  game.queue_trigger_event(Default::default(),ironsmith::triggers::TriggerEvent::new(ironsmith::events::BeginningOfEndStepEvent::new(A),Default::default()));
  drain(&mut game,&mut SelectFirstDecisionMaker);play::resolve_all(&mut game,&mut play::Script::default());
  assert_eq!(game.battlefield.iter().filter_map(|id|game.object(*id)).filter(|object|object.name=="Soldier").count(),expected);
 }}
}
#[test]fn actual_unerring_uses_the_donor_cast_origin_and_loses_this_turn_haste_later(){for definition in actual("Unerring Killer"){
 let mut game=play::game();mana(&mut game);let donor=game.create_object_from_definition(&definition,A,Zone::Graveyard);
 let fodder=ironsmith_compiler_runtime::compile_to_runtime_definition("One sacrifice","Type: Artifact",false).unwrap();game.create_object_from_definition(&fodder,A,Zone::Battlefield);
 let selected=action(&game,donor).unwrap();let copy=announce(&mut game,selected).unwrap();let stable=game.object(copy).unwrap().stable_id;
 ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();let token=game.find_object_by_stable_id(stable).unwrap();
 assert!(game.current_has_static_ability_id(token,ironsmith_core::StaticAbilityId::Haste));game.next_turn();assert!(!game.current_has_static_ability_id(token,ironsmith_core::StaticAbilityId::Haste));
}}
#[test]fn actual_gutter_rat_selects_only_owned_cards_with_the_supplied_keyword_in_exile(){
 for (rat,pursuit) in actual("Gutter Rat").into_iter().zip(actual("Guild Elite")){
  let mut game=play::game();let unmarked=ironsmith_compiler_runtime::compile_to_runtime_definition("Unmarked exiled card","Type: Artifact",false).unwrap();let unmarked=game.create_object_from_definition(&unmarked,A,Zone::Exile);
  let foreign=game.create_object_from_definition(&pursuit,B,Zone::Exile);let eligible=game.create_object_from_definition(&pursuit,A,Zone::Exile);let stable=game.object(eligible).unwrap().stable_id;
  let old=game.create_object_from_definition(&rat,A,Zone::Hand);enter(&mut game,old,&mut SelectFirstDecisionMaker);drain(&mut game,&mut SelectFirstDecisionMaker);play::resolve_all(&mut game,&mut play::Script::default());
  assert_eq!(game.object(unmarked).unwrap().zone,Zone::Exile);assert_eq!(game.object(foreign).unwrap().zone,Zone::Exile);assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Graveyard);
 }
}

struct Modes{accept:bool,selected:Vec<usize>,ranges:Vec<(usize,usize)>}
impl DecisionMaker for Modes{
 fn decide_boolean(&mut self,_:&GameState,_:&ironsmith::decisions::context::BooleanContext)->bool{self.accept}
 fn decide_options(&mut self,game:&GameState,context:&ironsmith::decisions::context::SelectOptionsContext)->Vec<usize>{if context.description.to_lowercase().contains("mode"){self.ranges.push((context.min,context.max));self.selected.clone()}else{SelectFirstDecisionMaker.decide_options(game,context)}}
}
#[test]fn actual_dawnhymn_changes_the_mode_range_to_zero_through_two_after_reprieving(){
 for definition in actual("Dawnhymn Herald"){for (accept,selected,life,soldiers,range) in [(false,vec![0],20,2,(1,1)),(true,vec![],20,0,(0,2)),(true,vec![0,2],25,2,(0,2))]{
  let mut game=play::game();let body=play::vanilla("Returnable creature","{1}","Elf",1,1);game.create_object_from_definition(&body,A,Zone::Battlefield);
  let old=game.create_object_from_definition(&definition,A,Zone::Hand);let mut dm=Modes{accept,selected,ranges:Vec::new()};enter(&mut game,old,&mut dm);drain(&mut game,&mut dm);
  while !game.stack.is_empty(){ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();}
  assert!(dm.ranges.contains(&range),"{:?}",dm.ranges);assert_eq!(game.player(A).unwrap().life,life);
  assert_eq!(game.battlefield.iter().filter_map(|id|game.object(*id)).filter(|object|object.name=="Soldier").count(),soldiers);
 }}
}

fn settle(game:&mut GameState){drain(game,&mut SelectFirstDecisionMaker);while !game.stack.is_empty(){ironsmith::game_loop::resolve_stack_entry_with(game,&mut SelectFirstDecisionMaker).unwrap();}}
#[test]fn actual_boundlight_returns_unless_it_completed_a_return_and_history_does_not_cross_reentry(){for definition in actual("Boundlight Seraph"){for accept in [false,true]{let mut game=play::game();let creature=play::vanilla("Returnable creature","{1}","Elf",1,1);game.create_object_from_definition(&creature,A,Zone::Battlefield);let old=game.create_object_from_definition(&definition,A,Zone::Hand);let stable=game.object(old).unwrap().stable_id;let source=enter(&mut game,old,&mut EntryChoices(VecDeque::from([accept])));settle(&mut game);let current=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.object(current).unwrap().zone,if accept{Zone::Battlefield}else{Zone::Hand});if accept{let result=execute_effect(&mut game,&ironsmith::Effect::move_to_zone(ChooseSpec::SpecificObject(source),Zone::Hand,false),&mut EffectContext::new_default(source,A)).unwrap();for event in result.events{game.queue_trigger_event(event.provenance(),event);}let hand=game.find_object_by_stable_id(stable).unwrap();let arrived=enter(&mut game,hand,&mut EntryChoices(VecDeque::from([false])));assert_eq!(game.named_action_count(arrived,"reprieve",false),0);settle(&mut game);assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Hand);}}}}
#[test]fn actual_choir_counts_zero_one_two_and_three_completed_returns(){for definition in actual("Choir Ascendant"){for accepted in 0..=3{let mut game=play::game();let body=play::vanilla("Returnable creature","{1}","Elf",1,1);for _ in 0..3{game.create_object_from_definition(&body,A,Zone::Battlefield);}let old=game.create_object_from_definition(&definition,A,Zone::Hand);enter(&mut game,old,&mut EntryChoices((0..3).map(|index|index<accepted).collect()));settle(&mut game);assert_eq!(game.battlefield.iter().filter_map(|id|game.object(*id)).filter(|object|object.name=="Angel").count(),accepted);}}}
#[test]fn actual_sentinel_replaces_the_bonus_instead_of_adding_both(){for definition in actual("Lunate Sentinel"){for accept in [false,true]{let mut game=play::game();let body=play::vanilla("Chosen creature","{1}","Elf",2,2);let target=game.create_object_from_definition(&body,B,Zone::Battlefield);game.create_object_from_definition(&body,A,Zone::Battlefield);let old=game.create_object_from_definition(&definition,A,Zone::Hand);enter(&mut game,old,&mut EntryChoices(VecDeque::from([accept])));settle(&mut game);assert_eq!(game.calculated_power(target),Some(if accept{6}else{4}));assert_eq!(game.calculated_toughness(target),Some(if accept{6}else{4}));}}}
#[test]fn actual_paragon_places_other_creature_counters_then_conditionally_grants_keywords(){for definition in actual("Paragon of Sacred Bellows"){for accept in [false,true]{let mut game=play::game();let body=play::vanilla("Other creature","{1}","Elf",2,2);game.create_object_from_definition(&body,A,Zone::Battlefield);let recipient=game.create_object_from_definition(&body,A,Zone::Battlefield);let old=game.create_object_from_definition(&definition,A,Zone::Hand);let source=enter(&mut game,old,&mut EntryChoices(VecDeque::from([accept])));settle(&mut game);assert_eq!(game.counter_count(source,ironsmith::object::CounterType::PlusOnePlusOne),0);assert_eq!(game.counter_count(recipient,ironsmith::object::CounterType::PlusOnePlusOne),1);for id in [source,recipient]{assert_eq!(game.current_has_static_ability_id(id,ironsmith_core::StaticAbilityId::Haste),accept);assert_eq!(game.current_has_static_ability_id(id,ironsmith_core::StaticAbilityId::Trample),accept);}}}}
#[test]fn actual_sanctum_noncreature_entry_enables_large_targets_and_duration_returns_them(){for definition in actual("Sanctum of Repression"){for (accept,mv,exiled) in [(false,2,true),(false,4,false),(true,4,true)]{let mut game=play::game();let target=play::vanilla("Opposing target",if mv==2{"{2}"}else{"{4}"},"Elf",2,2);let target=game.create_object_from_definition(&target,B,Zone::Battlefield);let target_stable=game.object(target).unwrap().stable_id;let body=play::vanilla("Returnable creature","{1}","Elf",1,1);game.create_object_from_definition(&body,A,Zone::Battlefield);let old=game.create_object_from_definition(&definition,A,Zone::Hand);let source=enter(&mut game,old,&mut EntryChoices(VecDeque::from([accept])));settle(&mut game);let moved=game.find_object_by_stable_id(target_stable).unwrap();assert_eq!(game.object(moved).unwrap().zone,if exiled{Zone::Exile}else{Zone::Battlefield});if exiled{let result=execute_effect(&mut game,&ironsmith::Effect::move_to_zone(ChooseSpec::SpecificObject(source),Zone::Graveyard,false),&mut EffectContext::new_default(source,A)).unwrap();for event in result.events{game.queue_trigger_event(event.provenance(),event);}settle(&mut game);assert_eq!(game.object(game.find_object_by_stable_id(target_stable).unwrap()).unwrap().zone,Zone::Battlefield);}}}}
#[test]fn actual_purifier_checks_target_value_or_source_return_history(){for definition in actual("Purifier of Dawnbloom Grove"){for (accept,mv,destroyed) in [(false,1,true),(false,2,false),(true,2,true)]{let mut game=play::game();let target=ironsmith_compiler_runtime::compile_to_runtime_definition("Opposing artifact",format!("Mana cost: {{{mv}}}\nType: Artifact"),false).unwrap();let target=game.create_object_from_definition(&target,B,Zone::Battlefield);let stable=game.object(target).unwrap().stable_id;let body=play::vanilla("Returnable creature","{1}","Elf",1,1);game.create_object_from_definition(&body,A,Zone::Battlefield);let old=game.create_object_from_definition(&definition,A,Zone::Hand);enter(&mut game,old,&mut EntryChoices(VecDeque::from([accept])));settle(&mut game);assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,if destroyed{Zone::Graveyard}else{Zone::Battlefield});}}}
#[test]fn actual_vanguard_replaces_the_search_filter_without_searching_twice(){for definition in actual("Dawnspark Vanguard"){for accept in [false,true]{let mut game=play::game();let nonbasic=ironsmith_compiler_runtime::compile_to_runtime_definition("Nonbasic land","Type: Land",false).unwrap();let basic=ironsmith_compiler_runtime::compile_to_runtime_definition("Basic land","Type: Basic Land — Forest",false).unwrap();let nonbasic=game.create_object_from_definition(&nonbasic,A,Zone::Library);let basic=game.create_object_from_definition(&basic,A,Zone::Library);let nonbasic_stable=game.object(nonbasic).unwrap().stable_id;let basic_stable=game.object(basic).unwrap().stable_id;let body=play::vanilla("Returnable creature","{1}","Elf",1,1);game.create_object_from_definition(&body,A,Zone::Battlefield);let old=game.create_object_from_definition(&definition,A,Zone::Hand);enter(&mut game,old,&mut EntryChoices(VecDeque::from([accept])));settle(&mut game);assert_eq!(game.object(game.find_object_by_stable_id(nonbasic_stable).unwrap()).unwrap().zone,if accept{Zone::Hand}else{Zone::Library});assert_eq!(game.object(game.find_object_by_stable_id(basic_stable).unwrap()).unwrap().zone,if accept{Zone::Library}else{Zone::Hand});assert_eq!(game.player(A).unwrap().library.len(),1);}}}

#[test]fn actual_founders_total_price_keeps_life_payment_and_mana_separate(){for definition in actual("The Founder's Hunt Begins"){for life in [2,20]{let mut game=play::game();game.player_mut(A).unwrap().life=life;mana(&mut game);let donor=game.create_object_from_definition(&definition,A,Zone::Graveyard);let artifact=ironsmith_compiler_runtime::compile_to_runtime_definition("Sacrifice artifact","Type: Artifact",false).unwrap();game.create_object_from_definition(&artifact,A,Zone::Battlefield);game.create_object_from_definition(&artifact,A,Zone::Library);let selected=action(&game,donor);if life==2{assert!(selected.is_none(),"mandatory printed life component is not discarded");continue;}announce(&mut game,selected.unwrap()).unwrap();assert_eq!(game.player(A).unwrap().life,17);assert_eq!(game.player(A).unwrap().mana_pool.total(),37);}}}
#[test]fn actual_pursuit_keeps_creature_timing_source_zone_and_ownership_restrictions(){for definition in actual("Guild Elite"){let mut game=play::game();mana(&mut game);let artifact=ironsmith_compiler_runtime::compile_to_runtime_definition("Sacrifice artifact","Type: Artifact",false).unwrap();game.create_object_from_definition(&artifact,A,Zone::Battlefield);let donor=game.create_object_from_definition(&definition,A,Zone::Graveyard);assert!(action(&game,donor).is_some());game.turn.active_player=B;assert!(action(&game,donor).is_none());game.turn.active_player=A;let foreign=game.create_object_from_definition(&definition,B,Zone::Graveyard);assert!(action(&game,foreign).is_none());let exiled=game.move_object_by_effect(donor,Zone::Exile).unwrap();assert!(action(&game,exiled).is_none());}}
#[test]fn prevented_donor_exile_cannot_leave_a_paid_orphan_copy_or_consume_resources(){for definition in actual("Guild Elite"){let mut game=play::game();mana(&mut game);let donor=game.create_object_from_definition(&definition,A,Zone::Graveyard);let stable=game.object(donor).unwrap().stable_id;let artifact=ironsmith_compiler_runtime::compile_to_runtime_definition("Sacrifice artifact","Type: Artifact",false).unwrap();let fodder=game.create_object_from_definition(&artifact,A,Zone::Battlefield);let fodder_stable=game.object(fodder).unwrap().stable_id;let selected=action(&game,donor).unwrap();let mut replacement=ironsmith::replacement::ZoneReplacementSpec::new(ironsmith::ObjectFilter::specific(donor),Zone::Exile).from_zone(Zone::Graveyard).to_zone(Zone::Exile).build(fodder,A);replacement.replacement=ironsmith::replacement::ReplacementAction::Prevent;game.effect_store.replacement_effects.add_one_shot_effect(replacement);assert!(announce(&mut game,selected).is_err());assert!(game.stack.is_empty());assert_eq!(game.player(A).unwrap().mana_pool.total(),40);assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Graveyard);assert_eq!(game.object(game.find_object_by_stable_id(fodder_stable).unwrap()).unwrap().zone,Zone::Battlefield);}}
#[test]fn prevented_or_redirected_optional_return_does_not_record_a_reprieved_creature(){for definition in actual("Boundlight Seraph"){for prevent in [false,true]{let mut game=play::game();let body=play::vanilla("Returnable creature","{1}","Elf",1,1);let victim=game.create_object_from_definition(&body,A,Zone::Battlefield);let stable=game.object(victim).unwrap().stable_id;let old=game.create_object_from_definition(&definition,A,Zone::Hand);let source_stable=game.object(old).unwrap().stable_id;let mut replacement=ironsmith::replacement::ZoneReplacementSpec::new(ironsmith::ObjectFilter::specific(victim),Zone::Exile).from_zone(Zone::Battlefield).to_zone(Zone::Hand).build(victim,A);if prevent{replacement.replacement=ironsmith::replacement::ReplacementAction::Prevent;}game.effect_store.replacement_effects.add_one_shot_effect(replacement);let source=enter(&mut game,old,&mut EntryChoices(VecDeque::from([true])));assert_eq!(game.named_action_count(source,"reprieve",false),0);assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,if prevent{Zone::Battlefield}else{Zone::Exile});settle(&mut game);assert_eq!(game.object(game.find_object_by_stable_id(source_stable).unwrap()).unwrap().zone,Zone::Hand);}}}
